<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<view class="change">
			<view class="change-info">
				<view class="tx-type">
					<view class="tit">提现方式</view>
					<view class="right">
						<view class="right-item" @click="changeTxType(1)">
							<image :src="form.tx_type==1?'/static/common/checkbox_select.png':'/static/common/checkbox_unselect.png'" mode="widthFix" class="check-img"/>
							<text>银行卡</text>
						</view>
						<view class="right-item" @click="changeTxType(2)" v-if="result.is_bind_wx==1">
							<image :src="form.tx_type==2?'/static/common/checkbox_select.png':'/static/common/checkbox_unselect.png'" mode="widthFix" class="check-img"/>
							<text>微信</text>
						</view>
					</view>
				</view>
				<view class="title">
					<view class="left">
						<text class="tit">提现金额</text>
						<text class="sxf">{{result.tx_kc_sxf_str}}</text>
					</view>
					<view class="right" @click="toNext(`/pages/my/withdraw-list`)">提现记录</view>
				</view>
				<view class="center">
					<text>¥</text>
					<view class="center-input">
						<u-input
						    placeholder="请输入提现金额"
							border="none"
							type="number"
							placeholderClass="placeholder30"
							v-model="form.money"
							fontSize="50rpx"
						    clearable />
					</view>
				</view>
				<view class="verify" v-if="result.user_with_sms_enable==1">
					<text class="text">验证码</text>
					<view class="row-input">
						<u-input
						    placeholder="请输入验证码"
							border="none"
							type="number"
							maxlength="6"
							placeholderClass="placeholder28"
							v-model="form.code"
						    clearable />
					</view>
					<button type="default" size="mini" class="code-btn" :disabled="codeDisabled" @click="getCode">{{tips}}</button>
				</view>
				<view class="change-bot">
					<view class="left">
						<text>{{result.yue_title}}</text>
						<text class="money">{{result.yue}}</text>
					</view>
					<view class="right" @click="changeAll">全部提现</view>
				</view>
			</view>
			<view class="submit">
				<button class="submit-btn" @click="submit" :disabled="submitDisabled">确认提现</button>
			</view>
		</view>
		</block>
		<u-code ref="uCode1" startText="获取验证码" :seconds="result.sms_time_out" @change="codeChange" keep-running change-text="Xs"
										@start="codeDisabled = true" @end="codeDisabled = false"></u-code>
	</view>
</template>

<script>
	var validate = require("@/components/validate/validate.js");
	var _this;
	export default {
		data() {
			return {
				form:{
					step:1,
					money:'',
					tx_type:1,
					code:''
				},
				result:{},
				submitDisabled:false,
				zhDisabled:false,
				tips:'获取验证码',
				codeDisabled:false,
			}
		},
		onLoad(e) {
			_this = this;
			_this.tixian()
		},
		methods: {
			changeTxType(tx_type){
				if(_this.form.tx_type==tx_type){
					return
				}
				_this.form.tx_type=tx_type
			},
			async tixian(){
				if(_this.form.step==2){
					var codeRule = {
						name: 'code',
						rules: ['require', 'integer', 'min:6'],
						errorMsg: {
							require: '请输入验证码',
							integer: '验证码只能为数字',
							min: '验证码为6位'
						}
					}
					var rule = [
					{
						name: 'money',
						rules: ['require', 'number'],
						errorMsg: {
							require: '提现金额不能为空',
							number: '提现金额只能为数字',
						}
					}];
					if(_this.result.user_with_sms_enable==1){
						rule.push(codeRule);
					}
					// 是否全部通过，返回Boolean
					let checked = validate.check(this.form, rule);
					if (!checked) {
						// 获取错误信息
						let err = validate.getError();
						uni.$u.toast(err[0])
						return;
					}
				}
				const data = await _this.$post('port/tixian', _this.form)
				if(data.code==1){
					uni.$u.toast(data.msg)
					_this.result.yue = data.result.yue
				}else if(data.code==-100){
					uni.$u.toast(data.msg)
					_this.result = data.result
					_this.submitDisabled = true
					_this.zhDisabled = true
				}else if(data.code==-2){
					_this.result = data.result
				}else if(data.code==-10){
					uni.$u.toast(data.msg)
					//跳转到完善信息界面
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/my/user-info?is_tx=1`,true)
					})
				}else{
					uni.$u.toast(data.msg)
				}
				if (_this.load) {
					_this.load = false
				}
			},
			changeAll(){
				if(_this.zhDisabled){
					return
				}
				_this.form.money = _this.result.yue
			},
			//获取验证码
			async getCode() {
				//单独验证使用
				// let check = validate.checkResult('mobile', this.phone);
				// if (!check) {
				// 	uni.$u.toast("手机号码格式有误")
				// 	return
				// }
				if (this.$refs.uCode1.canGetCode) {
					const params = {
						scene: 'tixian'
					}
					const data = await _this.$post('port/transmit',params)
					if (data.code == 1) {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast('发送成功');
						// 通知验证码组件内部开始倒计时
						this.$refs.uCode1.start();
					} else {
						// 这里此提示会被this.start()方法中的提示覆盖
						uni.$u.toast(data.msg);
					}
				} else {
					uni.$u.toast('请倒计时结束后再发送');
				}
			},
			codeChange(text) {
				_this.tips = text;
			},
			async submit(){
				_this.form.step = 2
				_this.tixian()
			}
		}
	}
</script>

